import{c as a,Q as s,j as n,m as o}from"./chunks/framework.DVSyX6JR.js";const g=JSON.parse('{"title":"Power saving","description":"","frontmatter":{},"headers":[],"relativePath":"docs/power-saving.md","filePath":"docs/power-saving.md"}'),t={name:"docs/power-saving.md"};function r(i,e,p,l,d,h){return s(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="power-saving" tabindex="-1">Power saving <a class="header-anchor" href="#power-saving" aria-label="Permalink to &quot;Power saving&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Power saving lets a repeater sleep when it has nothing to transmit. This is useful for battery-powered or solar-powered nodes.</p><p>The default is <strong>off</strong>. Many repeaters are fixed relay or backbone nodes and should not sleep unexpectedly.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>powersaving          — show current state</span></span>
<span class="line"><span>powersaving on       — enable power saving</span></span>
<span class="line"><span>powersaving off      — disable power saving</span></span>
<span class="line"><span></span></span>
<span class="line"><span>get power.stats      — show sleep/wake statistics</span></span>
<span class="line"><span>clear power.stats    — reset statistics</span></span></code></pre></div><h2 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h2><p>When power saving is enabled:</p><ul><li>The repeater sleeps only when there is <strong>no outbound work pending</strong>.</li><li>Bridge or WiFi mode <strong>blocks sleep</strong> — a bridged repeater stays awake.</li><li><strong>ESP32 boards</strong> wake via LoRa DIO1 or timer where supported.</li><li><strong>nRF52 boards</strong> use event/interrupt sleep.</li></ul><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><p><code>get power.stats</code> shows how often and how long the repeater has slept. Stats are RAM-only and reset on reboot or when cleared with <code>clear power.stats</code>.</p>`,11)])])}const w=a(t,[["render",r]]);export{g as __pageData,w as default};
